import{_ as s,a0 as l,w as r,s as d,ao as a,I as i,x as e,a1 as n,A as p}from"./chunks/framework.ePQ6-oQR.js";import"./chunks/theme.D0YJYoYq.js";const _=JSON.parse('{"title":"Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障 | LCTT x X-CMD","titleTemplate":false,"description":"Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障 | LCTT (201509) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障 | LCTT (201509) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting","title":"Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障","tag":"201509","desc":""},"relativePath":"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting.md","filePath":"[post].md"}'),g={name:"201509/20150806 Linux FAQs with Answers--How to enable logging in Open vSwitch for debugging and troubleshooting.md"};function c(u,t,f,v,m,O){const o=l("Link");return r(),d("div",null,[t[13]||(t[13]=a(`<h1 id="linux有问必答-如何启用open-vswitch的日志功能以便调试和排障" tabindex="-1">Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障 <a class="header-anchor" href="#linux有问必答-如何启用open-vswitch的日志功能以便调试和排障" aria-label="Permalink to “Linux有问必答：如何启用Open vSwitch的日志功能以便调试和排障”">​</a></h1><blockquote><p><strong>问题</strong> 我试着为我的Open vSwitch部署排障，鉴于此，我想要检查它的由内建日志机制生成的调试信息。我怎样才能启用Open vSwitch的日志功能，并且修改它的日志等级（如，修改成INFO/DEBUG级别）以便于检查更多详细的调试信息呢？</p></blockquote><p>Open vSwitch（OVS)是Linux平台上最流行的开源的虚拟交换机。由于当今的数据中心日益依赖于软件定义网络（SDN）架构，OVS被作为数据中心的SDN部署中的事实标准上的网络元素而得到飞速应用。</p><p>Open vSwitch具有一个内建的日志机制，它称之为VLOG。VLOG工具允许你在各种网络交换组件中启用并自定义日志，由VLOG生成的日志信息可以被发送到一个控制台、syslog以及一个便于查看的单独日志文件。你可以通过一个名为<code>ovs-appctl</code>的命令行工具在运行时动态配置OVS日志。</p><p><img src="https://farm1.staticflickr.com/499/19300367114_cd8aac2fb2_c.jpg" alt=""></p><p>这里为你演示如何使用<code>ovs-appctl</code>启用Open vSwitch中的日志功能，并进行自定义。</p><p>下面是<code>ovs-appctl</code>自定义VLOG的语法。</p><pre><code>$ sudo ovs-appctl vlog/set module[:facility[:level]] 
</code></pre><ul><li><strong>Module</strong>：OVS中的任何合法组件的名称（如netdev，ofproto，dpif，vswitchd等等）</li><li><strong>Facility</strong>：日志信息的目的地（必须是：console，syslog，或者file）</li><li><strong>Level</strong>：日志的详细程度（必须是：emer，err，warn，info，或者dbg）</li></ul><p>在OVS源代码中，模块名称在源文件中是以以下格式定义的：</p><pre><code>VLOG_DEFINE_THIS_MODULE(&lt;module-name&gt;);
</code></pre><p>例如，在lib/netdev.c中，你可以看到：</p><pre><code>VLOG_DEFINE_THIS_MODULE(netdev);
</code></pre><p>这个表明，lib/netdev.c是netdev模块的一部分，任何在lib/netdev.c中生成的日志信息将属于netdev模块。</p><p>在OVS源代码中，有多个严重度等级用于定义几个不同类型的日志信息：VLOG_INFO()用于报告，VLOG_WARN()用于警告，VLOG_ERR()用于错误提示，VLOG_DBG()用于调试信息，VLOG_EMERG用于紧急情况。日志等级和工具确定哪个日志信息发送到哪里。</p><p>要查看可用模块、工具和各自日志级别的完整列表，请运行以下命令。该命令必须在你启动OVS后调用。</p><pre><code>$ sudo ovs-appctl vlog/list 
</code></pre><p><img src="https://farm1.staticflickr.com/465/19734939478_7eb5d44635_c.jpg" alt=""></p><p>输出结果显示了用于三个场合（facility：console，syslog，file）的各个模块的调试级别。默认情况下，所有模块的日志等级都被设置为INFO。</p><p>指定任何一个OVS模块，你可以选择性地修改任何特定场合的调试级别。例如，如果你想要在控制台屏幕中查看dpif更为详细的调试信息，可以运行以下命令。</p><pre><code>$ sudo ovs-appctl vlog/set dpif:console:dbg 
</code></pre><p>你将看到dpif模块的console工具已经将其日志等级修改为DBG，而其它两个场合syslog和file的日志级别仍然没有改变。</p><p><img src="https://farm1.staticflickr.com/333/19896760146_5d851311ae_c.jpg" alt=""></p><p>如果你想要修改所有模块的日志等级，你可以指定“ANY”作为模块名。例如，下面命令将修改每个模块的console的日志级别为DBG。</p><pre><code>$ sudo ovs-appctl vlog/set ANY:console:dbg 
</code></pre><p><img src="https://farm1.staticflickr.com/351/19734939828_8c7f59e404_c.jpg" alt=""></p><p>同时，如果你想要一次性修改所有三个场合的日志级别，你可以指定“ANY”作为场合名。例如，下面的命令将修改每个模块的所有场合的日志级别为DBG。</p><pre><code>$ sudo ovs-appctl vlog/set ANY:ANY:dbg 
</code></pre><hr>`,29)),i("p",null,[t[1]||(t[1]=e("via: ",-1)),n(o,{href:"http://ask.xmodulo.com/enable-logging-open-vswitch.html"},{default:p(()=>[...t[0]||(t[0]=[e("http://ask.xmodulo.com/enable-logging-open-vswitch.html",-1)])]),_:1})]),i("p",null,[t[5]||(t[5]=e("作者：",-1)),n(o,{href:"http://ask.xmodulo.com/author/nanni"},{default:p(()=>[...t[2]||(t[2]=[e("Dan Nanni",-1)])]),_:1}),t[6]||(t[6]=e(" 译者：",-1)),n(o,{href:"https://github.com/GOLinux"},{default:p(()=>[...t[3]||(t[3]=[e("GOLinux",-1)])]),_:1}),t[7]||(t[7]=e(" 校对：",-1)),n(o,{href:"https://github.com/wxy"},{default:p(()=>[...t[4]||(t[4]=[e("wxy",-1)])]),_:1})]),i("p",null,[t[10]||(t[10]=e("本文由 ",-1)),n(o,{href:"https://github.com/LCTT/TranslateProject"},{default:p(()=>[...t[8]||(t[8]=[e("LCTT",-1)])]),_:1}),t[11]||(t[11]=e(" 原创翻译，",-1)),n(o,{href:"https://linux.cn/"},{default:p(()=>[...t[9]||(t[9]=[e("Linux中国",-1)])]),_:1}),t[12]||(t[12]=e(" 荣誉推出",-1))])])}const h=s(g,[["render",c]]);export{_ as __pageData,h as default};
